@cuda.jit
def _batch1024_factor_two_cta(source, destination, flags, epoch):
    sample = cuda.blockIdx.x // 2
    worker = cuda.blockIdx.x - sample * 2
    sample_base = sample * _D256_MATRIX_ELEMENTS
    marker_index = sample * 2
    arrival_index = marker_index + 1
    shared = cuda.shared.array(shape=0, dtype=np.float32, alignment=16)
    a_shared = shared[0:_D256_FP32_TILE_ELEMENTS]
    b_shared = shared[
        _D256_FP32_TILE_ELEMENTS : 2 * _D256_FP32_TILE_ELEMENTS
    ]
    update_start = 2 * _D256_FP32_TILE_ELEMENTS
    update_shared = shared[
        update_start : update_start + _D256_HALF_TILE_ELEMENTS
    ].view(np.float16)
    c_shared = update_shared[0:_D256_HALF_TILE_ELEMENTS]
    d_shared = update_shared[
        _D256_HALF_TILE_ELEMENTS : 2 * _D256_HALF_TILE_ELEMENTS
    ]
    local_info = shared[
        update_start + _D256_HALF_TILE_ELEMENTS :
    ].view(np.int32)

    tile_count = _D256_N // _D256_NB
    for k in range(tile_count):
        if worker == 0:
            if k == 0:
                _d256_load_diagonal(source, sample_base, k, a_shared)
            else:
                _d256_load_first_diagonal_update(
                    source,
                    destination,
                    sample_base,
                    k,
                    a_shared,
                    c_shared,
                )
                _d256_gemm.execute(
                    -1.0, c_shared, c_shared, 1.0, a_shared
                )
                cuda.syncthreads()
            for i in range(1, k):
                _d256_load_tile(
                    destination,
                    sample_base,
                    i,
                    k,
                    c_shared,
                    _D256_HALF_LD,
                )
                _d256_gemm.execute(
                    -1.0, c_shared, c_shared, 1.0, a_shared
                )
                cuda.syncthreads()
            _d256_cholesky.factorize(
                a_shared, local_info, lda=_D256_FP32_LD
            )
            _d256_store_tile(
                a_shared, destination, sample_base, k, k, True
            )
        cuda.syncthreads()
        token = epoch * tile_count + k + 1
        if cuda.threadIdx.x == 0:
            if worker == 0:
                cuda.threadfence()
                cuda.atomic.exch(flags, marker_index, token)
            else:
                while cuda.atomic.add(flags, marker_index, 0) != token:
                    pass
        cuda.syncthreads()

        if k + 1 < tile_count:
            has_panel = k + 1 + worker < tile_count
            if worker != 0 and has_panel:
                _d256_load_tile(
                    destination,
                    sample_base,
                    k,
                    k,
                    a_shared,
                    _D256_FP32_LD,
                )
            for j in range(k + 1 + worker, tile_count, 2):
                if k == 0:
                    _d256_load_tile(
                        source,
                        sample_base,
                        k,
                        j,
                        b_shared,
                        _D256_FP32_LD,
                    )
                else:
                    _d256_load_first_panel_update(
                        source,
                        destination,
                        sample_base,
                        k,
                        j,
                        b_shared,
                        c_shared,
                        d_shared,
                    )
                    _d256_gemm.execute(
                        -1.0, c_shared, d_shared, 1.0, b_shared
                    )
                    cuda.syncthreads()
                for i in range(1, k):
                    _d256_load_tile_pair(
                        destination,
                        sample_base,
                        i,
                        k,
                        c_shared,
                        j,
                        d_shared,
                    )
                    _d256_gemm.execute(
                        -1.0, c_shared, d_shared, 1.0, b_shared
                    )
                    cuda.syncthreads()
                _d256_triangular.solve(
                    a_shared,
                    b_shared,
                    lda=_D256_FP32_LD,
                    ldb=_D256_FP32_LD,
                )
                _d256_store_tile(
                    b_shared, destination, sample_base, k, j, False
