            if has_panel:
                cuda.syncthreads()
                cuda.threadfence()
                if cuda.threadIdx.x == 0 and worker != 0:
                    cuda.atomic.exch(flags, arrival_index, token)
            if (
                cuda.threadIdx.x == 0
                and worker == 0
                and k + 2 < tile_count
